// Single line comment. /* Block comments nest in Dart. */
/// Doc comments attach to the declaration below.

void main() {
  final name = 'Ada';     // inferred String, never reassigned
  var visits = 3;         // inferred int, can change
  const limit = 5;        // compile-time constant

  visits += 1;
  print('$name has $visits visits, limit ${limit * 2}');

  // Cascades run several calls on the same object.
  final buffer = StringBuffer()
    ..write('id=')
    ..write(42);
  print(buffer.toString()); // id=42
}

