typedef Mapper = int Function(int);

List<int> transform(List<int> values, Mapper mapper) =>
    [for (final value in values) mapper(value)];

Mapper multiplier(int factor) => (value) => value * factor;

void main() {
  final triple = multiplier(3);
  print(transform([1, 2, 3], triple));        // [3, 6, 9]
  print(transform([1, 2, 3], (v) => v + 10)); // [11, 12, 13]
  print(triple.call(4));                      // 12
}

T largest<T extends Comparable<T>>(List<T> items) {
  var best = items.first;
  for (final item in items.skip(1)) {
    if (item.compareTo(best) > 0) best = item;
  }
  return best;
}

void main() {
  print(largest([3, 9, 4]));              // 9
  print(largest(['pear', 'fig', 'kiwi'])); // pear
}

import 'dart:math' show sqrt;

class Point {
  Point(this.x, this.y);

  Point.origin()
      : x = 0,
        y = 0;

  Point.fromJson(Map<String, num> json)
      : x = json['x']!.toDouble(),
        y = json['y']!.toDouble();

  final double x;
  final double y;

  double get distance => sqrt(x * x + y * y);
}

void main() {
  final origin = Point.origin();
  final parsed = Point.fromJson({'x': 3, 'y': 4});
  print(origin.x);        // 0.0
  print(parsed.distance); // 5.0
}

abstract class Shape {
  const Shape(this.name);

  final String name;

  double area();

  @override
  String toString() => '$name with area ${area().toStringAsFixed(2)}';
}

class Circle extends Shape {
  const Circle(this.radius) : super('circle');

  final double radius;

  @override
  double area() => 3.14159 * radius * radius;
}

class Square implements Shape {
  const Square(this.side);

  @override
  final String name = 'square';
  final double side;

  @override
  double area() => side * side;
}

void main() {
  print(Circle(2)); // circle with area 12.57
  print(Square(3)); // square with area 9.00
}

