// Sealed subclasses make this switch exhaustive.
String describe(Payment payment) => switch (payment) {
      CardPayment(:final last4) => 'card ending $last4',
      CashPayment(:final amount) => 'cash ${amount.toStringAsFixed(2)}',
    };

void main() {
  print(describe(CardPayment('4242'))); // card ending 4242
  print(describe(CashPayment(19.9)));   // cash 19.90
}

