void main() {
  final numbers = [4, 1, 7, 3, 9, 2];

  final doubled = numbers.map((n) => n * 2).toList();
  final evens = numbers.where((n) => n.isEven).toList();
  final total = numbers.fold(0, (sum, n) => sum + n);
  final sorted = [...numbers]..sort();

  print(doubled);                  // [8, 2, 14, 6, 18, 4]
  print(evens);                    // [4, 2]
  print(total);                    // 26
  print(sorted.first);             // 1
  print(numbers.any((n) => n > 8)); // true
}

void main() {
  final flags = [true, false, true];
  final labels = <String>[
    'start',
    if (flags.contains(true)) 'has-true',
    for (var i = 0; i < 2; i++) 'item-$i',
    ...['end'],
  ];
  print(labels); // [start, has-true, item-0, item-1, end]

  final counts = <String, int>{};
  for (final word in ['a', 'b', 'a']) {
    counts.update(word, (value) => value + 1, ifAbsent: () => 1);
  }
  print(counts); // {a: 2, b: 1}
}

Future<String> fetchUser(int id) async {
  await Future<void>.delayed(const Duration(milliseconds: 200));
  if (id <= 0) {
    throw ArgumentError.value(id, 'id', 'must be positive');
  }
  return 'user-$id';
}

Future<void> main() async {
  print(await fetchUser(7)); // user-7

  try {
    await fetchUser(0);
  } on ArgumentError catch (error) {
    print(error.message); // must be positive
  } finally {
    print('done'); // done
  }
}

Future<int> load(String name) async {
  await Future<void>.delayed(
    Duration(milliseconds: name.length * 10),
  );
  return name.length;
}

Future<void> main() async {
  // Both requests start together and finish together.
  final lengths = await Future.wait([load('one'), load('three')]);
  print(lengths); // [3, 5]

  try {
    await Future.wait([
      load('ok'),
      Future<int>.error(StateError('boom')),
    ]);
  } on StateError catch (error) {
    print(error.message); // boom
  }
}

import 'dart:async';

Future<int> slowTask() => Future<int>.delayed(
      const Duration(seconds: 2),
      () => 42,
    );

Future<void> main() async {
  try {
    final value = await slowTask()
        .timeout(const Duration(milliseconds: 500));
    print(value);
  } on TimeoutException {
    print('gave up waiting'); // gave up waiting
  }
}

Stream<int> countdown(int from) async* {
  for (var i = from; i > 0; i--) {
    await Future<void>.delayed(const Duration(milliseconds: 100));
    yield i;
  }
}

Future<void> main() async {
  await for (final value in countdown(3)) {
    print(value); // 3, then 2, then 1
  }
  print('liftoff'); // liftoff
}

import 'dart:async';

Future<void> main() async {
  final controller = StreamController<String>();
  final finished = Completer<void>();

  controller.stream.listen(
    (value) => print('data: $value'),
    onError: (Object error) => print('error: $error'),
    onDone: finished.complete,
  );

  controller.add('alpha');
  controller.add('beta');
  controller.addError(StateError('lost connection'));
  await controller.close();
  await finished.future;
}

import 'dart:async';

Future<void> main() async {
  // take(3) closes the periodic stream after three events.
  final ticks = Stream.periodic(
    const Duration(milliseconds: 50),
    (i) => i,
  ).take(3);
  print(await ticks.toList()); // [0, 1, 2]

  await for (final tick in Stream.fromIterable([10, 20, 30])) {
    print(tick); // 10, 20, 30
  }
}

