extension StringExtras on String {
  String get capitalized =>
      isEmpty ? this : '${this[0].toUpperCase()}${substring(1)}';

  String shout() => toUpperCase();
}

void main() {
  print('dart'.capitalized);         // Dart
  print('hi there'.shout());         // HI THERE
  print(''.capitalized.isEmpty);     // true
}

extension FirstWhereOrNull<T> on Iterable<T> {
  T? firstWhereOrNull(bool Function(T) test) {
    for (final value in this) {
      if (test(value)) return value;
    }
    return null;
  }
}

extension Blank on String? {
  bool get isBlank => this == null || this!.trim().isEmpty;
}

void main() {
  print([4, 7, 9].firstWhereOrNull((n) => n.isEven)); // 4
  print([1, 3].firstWhereOrNull((n) => n.isEven));    // null
  String? empty;
  print(empty.isBlank); // true
  print('  '.isBlank);  // true
  print('hi'.isBlank);  // false
}

