import 'package:test/test.dart';

int parsePort(String raw) {
  final port = int.parse(raw);
  if (port < 1 || port > 65535) {
    throw RangeError.range(port, 1, 65535, 'raw');
  }
  return port;
}

void main() {
  group('parsePort', () {
    test('accepts the usual range', () {
      expect(parsePort('8080'), 8080);
    });

    test('rejects garbage', () {
      expect(() => parsePort('http'), throwsFormatException);
    });

    test('rejects out of range', () {
      expect(() => parsePort('70000'), throwsA(isA<RangeError>()));
    });
  });
}

import 'package:test/test.dart';

class Counter {
  int value = 0;

  void increment() => value++;
}

void main() {
  late Counter counter;

  setUp(() {
    counter = Counter();
  });

  test('starts at zero', () {
    expect(counter.value, 0);
  });

  test('grows after delayed work', () async {
    await Future<void>.delayed(const Duration(milliseconds: 10));
    counter.increment();
    expect(counter.value, 1);
  });
}

