Future<void> main() async {
  final ids = [1, 2, 3];

  // forEach does not await: the callbacks keep running after it returns.
  ids.forEach((id) async {
    await Future<void>.delayed(Duration(milliseconds: id * 10));
  });
  print('printed before the delays finish');

  for (final id in ids) {
    await Future<void>.delayed(Duration(milliseconds: id * 10));
  }
  print('printed after every delay');
}
